content:
name: Diagnose bounded Windows metadata scheduling
on:
  push:
    branches: ['diagnostic/pali-held234-io-*']
permissions:
  contents: read
jobs:
  held234-scheduling:
    runs-on: windows-latest
    timeout-minutes: 15
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 2
          persist-credentials: false
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - uses: actions/setup-python@v5
        with:
          python-version: '3.12'
      - name: Compare original bounded wrappers with isolated and concurrent files
        shell: bash
        run: |
          node --input-type=module <<'JS'
          import {spawnSync} from 'node:child_process';
          import {mkdirSync,writeFileSync} from 'node:fs';
          import {join} from 'node:path';
          import {availableParallelism,cpus,totalmem,freemem,release} from 'node:os';
          import {performance} from 'node:perf_hooks';
          const base='7b613cedc63a2ffd80dd8257069070e6638829ef';
          const out=join(process.env.RUNNER_TEMP,'held234-scheduling');
          mkdirSync(out,{recursive:true});
          function git(args){const r=spawnSync('git',args,{encoding:'utf8',timeout:10000,maxBuffer:256*1024});if(r.error||r.status!==0)throw Error('Bounded Git provenance read failed: '+args.join(' '));return r.stdout.trim();}
          const metadata={base,head:git(['rev-parse','HEAD']),parent:git(['rev-parse','HEAD^']),delta:git(['diff','--name-status','HEAD^','HEAD']),node:process.version,platform:process.platform,arch:process.arch,os_release:release(),logical_cpus:cpus().length,available_parallelism:availableParallelism(),total_memory_bytes:totalmem(),free_memory_bytes:freemem(),purpose:'Scheduling contrast only. Not release CI or permission to promote dev.'};
          writeFileSync(join(out,'metadata.json'),JSON.stringify(metadata,null,2)+'\n');
          if(metadata.parent!==base||metadata.delta!=='A\t.github/workflows/pali-held234-io-diagnostic.yml'||git(['status','--porcelain'])!=='')throw Error('Diagnostic must differ from exact7b only by this workflow');
          const version=spawnSync('python3',['--version'],{encoding:'utf8',timeout:10000,maxBuffer:4096});
          if(version.error||version.status!==0||!/^Python [0-9]+\.[0-9]+\.[0-9]+\s*$/.test(version.stdout||version.stderr||''))throw Error('Bounded Python version probe failed');
          metadata.python_version=(version.stdout||version.stderr).trim();
          metadata.nominal_default_file_concurrency=Math.max(1,metadata.available_parallelism-1);
          metadata.inherited_concurrency_option=/--test-concurrency(?:=|\s)/.test(process.env.NODE_OPTIONS||'');
          if(metadata.inherited_concurrency_option)throw Error('Unexpected inherited concurrency option');
          writeFileSync(join(out,'metadata.json'),JSON.stringify(metadata,null,2)+'\n');
          console.log(JSON.stringify(metadata));
          const held='tests/held234-current333-chain.test.mjs';
          const focused=['tests/approved-current333-authority-negatives.test.mjs','tests/approved-current339-authority-negatives.test.mjs',held];
          const cases=[
            {name:'held-alone',args:['--test','--test-reporter=tap',held],limit:45000,expected:1},
            {name:'three-default',args:['--test','--test-reporter=tap',...focused],limit:metadata.nominal_default_file_concurrency<2?285000:160000,expected:3},
            {name:'three-serial',args:['--test','--test-reporter=tap','--test-concurrency=1',...focused],limit:285000,expected:3},
          ];
          const results=[];
          for(const item of cases){
            const started=new Date().toISOString(),t=performance.now();
            const r=spawnSync(process.execPath,item.args,{encoding:'utf8',timeout:item.limit,killSignal:'SIGKILL',maxBuffer:2*1024*1024});
            const record={name:item.name,argv:[process.execPath,...item.args],started_utc:started,completed_utc:new Date().toISOString(),elapsed_ms:performance.now()-t,outer_deadline_ms:item.limit,original_wrapper_child_deadlines_unchanged:true,status:r.status,signal:r.signal,error:r.error?{name:r.error.name,code:r.error.code,message:r.error.message}:null};
            writeFileSync(join(out,item.name+'.tap'),r.stdout||'');
            writeFileSync(join(out,item.name+'.stderr.log'),r.stderr||'');
            writeFileSync(join(out,item.name+'.json'),JSON.stringify(record,null,2)+'\n');
            const observed=Object.fromEntries([...((r.stdout||'').replace(/\r\n/g,'\n')).matchAll(/^# (tests|pass|fail|cancelled|skipped|todo) ([0-9]+)$/gm)].map(m=>[m[1],Number(m[2])]));
            record.expected_cases=item.expected;record.observed_counts=observed;
            record.complete_zero_skip_inventory=observed.tests===item.expected&&observed.cancelled===0&&observed.skipped===0&&observed.todo===0&&observed.pass+observed.fail===item.expected;
            record.successful_expected_cases=record.complete_zero_skip_inventory&&observed.pass===item.expected&&observed.fail===0;
            record.cleanup_unverified=Boolean(r.error||r.signal||r.status===null);
            writeFileSync(join(out,item.name+'.json'),JSON.stringify(record,null,2)+'\n');
            results.push(record);console.log(JSON.stringify(record));
            // An outer spawn error can leave worker descendants. Stop every
            // later contrast; runner teardown owns cleanup, never assume it.
            if(record.cleanup_unverified)break;
          }
          const after=git(['status','--porcelain']);
          writeFileSync(join(out,'results.json'),JSON.stringify({metadata,results,working_tree_after:after},null,2)+'\n');
          if(after!==''||results.length!==cases.length||results.some(r=>r.status!==0||r.error||r.signal||!r.successful_expected_cases))process.exitCode=1;
          JS
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: held234-windows22-scheduling
          path: ${{ runner.temp }}/held234-scheduling/
          if-no-files-found: error
